package gal.rodrigosambade.nfclab;
import android.nfc.*;import android.nfc.tech.*;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.nio.charset.StandardCharsets;
public class MainActivity extends AppCompatActivity implements NfcAdapter.ReaderCallback{NfcAdapter a;TextView status;EditText payload;Switch write;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);payload=findViewById(R.id.payload);write=findViewById(R.id.writeMode);a=NfcAdapter.getDefaultAdapter(this);if(a==null)status.setText("Sin NFC");}protected void onResume(){super.onResume();if(a!=null)a.enableReaderMode(this,this,NfcAdapter.FLAG_READER_NFC_A|NfcAdapter.FLAG_READER_NFC_B|NfcAdapter.FLAG_READER_NFC_F|NfcAdapter.FLAG_READER_NFC_V,null);}protected void onPause(){if(a!=null)a.disableReaderMode(this);super.onPause();}public void onTagDiscovered(Tag t){if(write.isChecked())writeText(t,payload.getText().toString());else read(t);}void read(Tag t){Ndef n=Ndef.get(t);if(n==null){post("Tag sin NDEF");return;}try{n.connect();NdefMessage m=n.getNdefMessage();StringBuilder b=new StringBuilder();if(m!=null)for(NdefRecord r:m.getRecords())b.append("TNF=").append(r.getTnf()).append(" payload=").append(new String(r.getPayload(),StandardCharsets.UTF_8)).append('\n');post(b.toString());}catch(Exception e){post(e.toString());}finally{try{n.close();}catch(Exception ignored){}}}void writeText(Tag t,String s){byte[] lang="es".getBytes(StandardCharsets.US_ASCII),body=s.getBytes(StandardCharsets.UTF_8),p=new byte[1+lang.length+body.length];p[0]=(byte)lang.length;System.arraycopy(lang,0,p,1,lang.length);System.arraycopy(body,0,p,1+lang.length,body.length);NdefMessage m=new NdefMessage(new NdefRecord(NdefRecord.TNF_WELL_KNOWN,NdefRecord.RTD_TEXT,new byte[0],p));Ndef n=Ndef.get(t);try{if(n!=null){n.connect();n.writeNdefMessage(m);n.close();}else{NdefFormatable f=NdefFormatable.get(t);if(f==null)throw new Exception("No formateable");f.connect();f.format(m);f.close();}post("NDEF escrito: "+s);}catch(Exception e){post(e.toString());}}void post(String s){runOnUiThread(()->status.setText(s));}}
